cat data/events.csv | tr -d '\r' | tail -n +2 | awk -F',' '{
  amount=$4
  cat=$5
  bad=0
  if (amount == "" || amount == "null") bad=1
  else {
    a = amount + 0
    if (a < 0 || a > 10000) bad=1
  }
  if (bad == 0) {
    valid = 0
    if (cat == "grocery") valid=1
    if (cat == "travel") valid=1
    if (cat == "salary") valid=1
    if (cat == "rent") valid=1
    if (cat == "other") valid=1
    if (valid == 0) bad=1
  }
  if (bad == 1) printf "\"%s\",\n", $1
}' | tr -d '\n' | sed 's/,$//'

